:import{
    -st-from: 'wix-ui-santa/index.st.css';
    -st-named: StylableButton
}
.root{
    -st-extends: StylableButton;
    transition: all 0.2s ease, visibility 0s;
    border: 2px solid #BDCBAE;
    background: rgba(189, 203, 174, 0)
}
.root:hover{
    background: #0038FF;
    border: 1px solid #0038FF
}
.root:hover::label{
    color: #FFFFFF
}
.root:disabled{
    background: #E2E2E2
}
.root:disabled::label{
    color: #8F8F8F
}
.root:disabled::icon{
    fill: #8F8F8F
}
.root::container{
    transition: inherit
}
.root::label{
    transition: inherit;
    margin: 0px 4px 0px 0px;
    letter-spacing: 0em;
    -st-mixin: font_8;
    font-size: 20px;
    font-weight: 700;
    font-family: proxima-n-w01-reg,proxima-n-w05-reg,sans-serif;
    color: #BDCBAE
}
.root::icon{
    transition: inherit;
    width: 10px;
    height: 10px;
    margin: 0px 0px 0px 4px;
    fill: #FFFFFF;
    display: none
}
.root:hover::icon{
    fill: #000000
}
@media value(mobileMediaQuery) {
    .root::label {
        -st-mixin: font_8;
        font-family: proxima-n-w01-reg,proxima-n-w05-reg,sans-serif;
        font-size: 12px;
        font-weight: 700;
    }
}
